        frames, --[[APR_DIAG]]
        APRTrace(
            "APR-Core/integrations/Gamepad.lua:260:callback#22", --[[/APR_DIAG]]
            function(a, b) return a.order < b.order end --[[APR_DIAG]]
        ) --[[/APR_DIAG]]
    )
    for _, entry in ipairs(frames) do
        self:ShowWindow(entry.frame)
    end
