watcher:SetScript(
    "OnEvent", --[[APR_DIAG]]
    APRTrace("APR-Core/integrations/Gamepad.lua:540:callback#46", --[[/APR_DIAG]] function(_, event, addon, action)
        if event == "ADDON_ACTION_FORBIDDEN" then
            Pad:RecordBlockedAction(addon, action)
